namespace PublicApi.Middleware;

public sealed class ApiKeyRateLimitOptions
{
    /// <summary>Requests each API key may make per window.</summary>
    public int Limit { get; set; } = 100;

    /// <summary>Fixed window length; every counter is dropped when the window rolls over.</summary>
    public TimeSpan Window { get; set; } = TimeSpan.FromMinutes(1);

    /// <summary>Request header carrying the API key.</summary>
    public string HeaderName { get; set; } = "X-Api-Key";
}

/// <summary>
/// Caps each API key at <see cref="ApiKeyRateLimitOptions.Limit"/> requests per
/// <see cref="ApiKeyRateLimitOptions.Window"/>. Counters live in a dictionary that is
/// replaced wholesale when the window rolls over, so keys that stop calling cost nothing.
/// State is per-process: behind more than one instance each replica gets its own budget.
/// </summary>
public sealed class ApiKeyRateLimitMiddleware
{
    /// <summary>Requests with no API key share one bucket so they cannot bypass the cap.</summary>
    private const string MissingKeyBucket = "<no-api-key>";

    private readonly RequestDelegate _next;
    private readonly ApiKeyRateLimitOptions _options;
    private readonly TimeProvider _timeProvider;
    private readonly object _rollLock = new();

    private ConcurrentDictionary<string, int> _counts = new(StringComparer.Ordinal);
    private long _windowStartTicks;

    public ApiKeyRateLimitMiddleware(
        RequestDelegate next,
        ApiKeyRateLimitOptions options,
        TimeProvider timeProvider)
    {
        _next = next;
        _options = options;
        _timeProvider = timeProvider;
        _windowStartTicks = timeProvider.GetUtcNow().UtcTicks;
    }

    public async Task InvokeAsync(HttpContext context)
    {
        var counts = CurrentWindow(out var windowStart);

        var key = context.Request.Headers[_options.HeaderName].ToString();
        if (string.IsNullOrWhiteSpace(key))
        {
            key = MissingKeyBucket;
        }

        var used = counts.AddOrUpdate(key, 1, static (_, current) => current + 1);
        var resetsAt = windowStart + _options.Window;

        context.Response.Headers["X-RateLimit-Limit"] = _options.Limit.ToString();
        context.Response.Headers["X-RateLimit-Remaining"] = Math.Max(0, _options.Limit - used).ToString();
        context.Response.Headers["X-RateLimit-Reset"] = resetsAt.ToUnixTimeSeconds().ToString();

        if (used > _options.Limit)
        {
            var retryAfter = (resetsAt - _timeProvider.GetUtcNow()).TotalSeconds;
            context.Response.StatusCode = StatusCodes.Status429TooManyRequests;
            context.Response.Headers.RetryAfter = ((int)Math.Ceiling(Math.Max(1d, retryAfter))).ToString();
            await context.Response.WriteAsJsonAsync(new
            {
                error = "rate_limit_exceeded",
                message = $"Limit of {_options.Limit} requests per {_options.Window.TotalSeconds:0} seconds exceeded.",
            });
            return;
        }

        await _next(context);
    }

    /// <summary>
    /// Returns the counter dictionary for the current window, starting a fresh one first if
    /// the previous window has elapsed.
    /// </summary>
    private ConcurrentDictionary<string, int> CurrentWindow(out DateTimeOffset windowStart)
    {
        var now = _timeProvider.GetUtcNow();

        if (now - WindowStart() >= _options.Window)
        {
            lock (_rollLock)
            {
                if (now - WindowStart() >= _options.Window)
                {
                    Volatile.Write(ref _counts, new ConcurrentDictionary<string, int>(StringComparer.Ordinal));
                    Interlocked.Exchange(ref _windowStartTicks, now.UtcTicks);
                }
            }
        }

        windowStart = WindowStart();
        return Volatile.Read(ref _counts);
    }

    private DateTimeOffset WindowStart() => new(Interlocked.Read(ref _windowStartTicks), TimeSpan.Zero);
}

public static class ApiKeyRateLimitMiddlewareExtensions
{
    public static IApplicationBuilder UseApiKeyRateLimit(
        this IApplicationBuilder app,
        Action<ApiKeyRateLimitOptions>? configure = null)
    {
        var options = new ApiKeyRateLimitOptions();
        configure?.Invoke(options);

        var timeProvider = app.ApplicationServices.GetService<TimeProvider>() ?? TimeProvider.System;
        return app.UseMiddleware<ApiKeyRateLimitMiddleware>(options, timeProvider);
    }
}
