using Identity.Api.Authentication;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Identity;
using Microsoft.AspNetCore.Mvc;

namespace Identity.Api.Controllers;

[ApiController]
[Route("auth")]
public sealed class AuthController(
    IUserCredentialStore users,
    IPasswordHasher<AppUser> passwordHasher,
    JwtTokenService tokenService) : ControllerBase
{
    [HttpPost("login")]
    [AllowAnonymous]
    [ProducesResponseType<LoginResponse>(StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status401Unauthorized)]
    public async Task<ActionResult<LoginResponse>> Login(
        LoginRequest request,
        CancellationToken cancellationToken)
    {
        var user = await users.FindByUsernameAsync(request.Username, cancellationToken);

        if (user is null)
        {
            // Hash anyway so a missing user costs the same as a wrong password and
            // the response time does not leak which usernames exist.
            passwordHasher.HashPassword(null!, request.Password);
            return Unauthorized();
        }

        var result = passwordHasher.VerifyHashedPassword(user, user.PasswordHash, request.Password);
        if (result == PasswordVerificationResult.Failed)
        {
            return Unauthorized();
        }

        var (accessToken, expiresIn) = tokenService.CreateAccessToken(user);
        return Ok(new LoginResponse(accessToken, "Bearer", expiresIn));
    }
}

public sealed record LoginRequest(
    [Required] string Username,
    [Required] string Password);

public sealed record LoginResponse(
    string AccessToken,
    string TokenType,
    int ExpiresIn);
