using System.Text.Json.Serialization;
using Identity.Api.Auth;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;

namespace Identity.Api.Controllers;

public sealed record LoginRequest(
    [property: Required] string Username,
    [property: Required] string Password);

public sealed record LoginResponse(
    [property: JsonPropertyName("access_token")] string AccessToken,
    [property: JsonPropertyName("token_type")] string TokenType,
    [property: JsonPropertyName("expires_in")] int ExpiresIn);

[ApiController]
[Route("auth")]
public sealed class AuthController : ControllerBase
{
    private readonly IUserCredentialValidator _credentials;
    private readonly ITokenService _tokens;

    public AuthController(IUserCredentialValidator credentials, ITokenService tokens)
    {
        _credentials = credentials;
        _tokens = tokens;
    }

    [AllowAnonymous]
    [HttpPost("login")]
    [ProducesResponseType<LoginResponse>(StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status401Unauthorized)]
    public async Task<IActionResult> Login([FromBody] LoginRequest request, CancellationToken cancellationToken)
    {
        var identity = await _credentials.ValidateAsync(request.Username, request.Password, cancellationToken);
        if (identity is null)
        {
            return Unauthorized();
        }

        var token = _tokens.CreateAccessToken(identity);
        return Ok(new LoginResponse(token.Value, "Bearer", token.ExpiresInSeconds));
    }
