using Microsoft.AspNetCore.Authentication.JwtBearer;
using Microsoft.Extensions.Options;

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddOptions<JwtOptions>()
    .Bind(builder.Configuration.GetSection(JwtOptions.SectionName))
    .ValidateDataAnnotations()
    .Validate(
        o => JwtOptions.IsUsableSigningKey(o.SigningKey),
        $"Jwt:SigningKey must be base64 and decode to at least {JwtOptions.MinimumKeyBytes} bytes for HS256.")
    .ValidateOnStart();

builder.Services.AddSingleton(TimeProvider.System);
builder.Services.AddSingleton<TokenService>();

// TODO: replace with the real user store before enabling /auth/login.
builder.Services.AddScoped<IUserAuthenticator, UnconfiguredUserAuthenticator>();

builder.Services.AddAuthentication().AddJwtBearer();

// Validate with the same key we sign with, so Jwt:SigningKey stays the single source of truth.
builder.Services.AddOptions<JwtBearerOptions>(JwtBearerDefaults.AuthenticationScheme)
    .PostConfigure<IOptions<JwtOptions>>((bearer, jwt) =>
        bearer.TokenValidationParameters.IssuerSigningKey = jwt.Value.GetSecurityKey());

builder.Services.AddAuthorization();
builder.Services.AddControllers();

var app = builder.Build();

app.UseAuthentication();
app.UseAuthorization();
