    private readonly IOptionsMonitor<JwtIssuerOptions> _options;","originalFile":"using System.IdentityModel.Tokens.Jwt;
using System.Security.Claims;
using Identity.Api.Auth;
using Microsoft.Extensions.Options;
using Microsoft.IdentityModel.Tokens;

namespace Identity.Api.Tokens;

public sealed record IssuedToken(string AccessToken, DateTimeOffset ExpiresAt);

public sealed class JwtTokenIssuer
{
    private readonly IOptionsMonitor<JwtIssuerOptions> _options;
    private readonly JwtSecurityTokenHandler _handler;

    public JwtTokenIssuer(IOptionsMonitor<JwtIssuerOptions> options)
    {
        _options = options;

        // Claims below are already written with their JWT names, so the handler's default
        // ClaimTypes.* -> short-name rewriting would only be a source of surprises.
        _handler = new JwtSecurityTokenHandler();
        _handler.OutboundClaimTypeMap.Clear();
    }

    public IssuedToken Issue(AuthenticatedUser user)
    {
        var options = _options.CurrentValue;

        var claims = new List<Claim>
        {
            new(JwtRegisteredClaimNames.Sub, user.Id),
            new(JwtRegisteredClaimNames.Jti, Guid.NewGuid().ToString("N")),
            new(JwtRegisteredClaimNames.PreferredUsername, user.Username),
        };
        // Literal "role", not ClaimTypes.Role: the outbound map that would shorten the long
        // ClaimTypes URI has been cleared above. Matches TokenValidationParameters.RoleClaimType.
        claims.AddRange(user.Roles.Select(role => new Claim(RoleClaimType, role)));

        var key = new SymmetricSecurityKey(Convert.FromBase64String(options.SigningKeys[0].Value!));
        var issuedAt = DateTime.UtcNow;
        var expires = issuedAt.AddMinutes(options.TokenLifetimeMinutes);

        var descriptor = new SecurityTokenDescriptor
        {
            Issuer = options.ValidIssuer,
            Audience = options.ValidAudiences[0],
            Subject = new ClaimsIdentity(claims),
            IssuedAt = issuedAt,
            NotBefore = issuedAt,
            Expires = expires,
            SigningCredentials = new SigningCredentials(key, SecurityAlgorithms.HmacSha256),
        };

        var token = _handler.CreateToken(descriptor);
        return new IssuedToken(_handler.WriteToken(token), new DateTimeOffset(expires, TimeSpan.Zero));
    }
}
