using Identity.Api.Tokens;
using Microsoft.AspNetCore.Authentication.JwtBearer;
using Microsoft.Extensions.Options;
using Microsoft.IdentityModel.Tokens;

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddAuthentication().AddJwtBearer();
builder.Services.AddAuthorization();
builder.Services.AddControllers();

builder.Services.AddSingleton<IValidateOptions<JwtIssuerOptions>, JwtIssuerOptionsValidator>();
builder.Services.AddOptions<JwtIssuerOptions>()
    .Bind(builder.Configuration.GetSection(JwtIssuerOptions.SectionName))
    .ValidateOnStart();
builder.Services.AddSingleton<JwtTokenIssuer>();

// Point the bearer handler at the very same key the issuer signs with, rather than relying on
// the configuration binder to pick up SigningKeys.
builder.Services.AddOptions<JwtBearerOptions>(JwtBearerDefaults.AuthenticationScheme)
    .Configure<IOptionsMonitor<JwtIssuerOptions>>((bearer, issuerOptions) =>
    {
        var options = issuerOptions.CurrentValue;
        bearer.TokenValidationParameters.IssuerSigningKey =
            new SymmetricSecurityKey(Convert.FromBase64String(options.SigningKeys[0].Value!));
    });

// TODO: swap for the real user store — see DenyAllUserCredentialStore.
builder.Services.AddSingleton<IUserCredentialStore, DenyAllUserCredentialStore>();

var app = builder.Build();

app.UseAuthentication();
app.UseAuthorization();
app.MapControllers();

app.Run();
