	}","originalFile":"package pallet

import (
	"errors"
	"fmt"
)

// LicencePlateLength is the length of a pallet licence plate: ten digits
// followed by a check digit.
const LicencePlateLength = 11

// Errors returned by ValidateLicencePlate and CheckDigit.
var (
	ErrLicencePlateLength     = errors.New("licence plate must be 11 characters")
	ErrLicencePlateDigits     = errors.New("licence plate must start with 10 digits")
	ErrLicencePlateCheckDigit = errors.New("licence plate check digit is wrong")
)

// CheckDigit returns the check digit for the ten digit body of a licence plate.
// It is the sum of each digit multiplied by its 1-based position, modulo 11,
// written as 'X' when that comes out as 10.
func CheckDigit(digits string) (byte, error) {
	if len(digits) != LicencePlateLength-1 {
		return 0, fmt.Errorf("%w: got %d", ErrLicencePlateLength, len(digits)+1)
	}
	sum := 0
	for i := 0; i < len(digits); i++ {
		c := digits[i]
		if c < '0' || c > '9' {
			return 0, fmt.Errorf("%w: %q at position %d", ErrLicencePlateDigits, c, i+1)
		}
		sum += int(c-'0') * (i + 1)
	}
	r := sum % 11
	if r == 10 {
		return 'X', nil
	}
	return byte('0' + r), nil
}

// ValidateLicencePlate reports whether plate is a well formed pallet licence
// plate: ten digits followed by the check digit described by CheckDigit. It
// returns nil when the plate is valid, otherwise an error wrapping one of
// ErrLicencePlateLength, ErrLicencePlateDigits or ErrLicencePlateCheckDigit.
func ValidateLicencePlate(plate string) error {
	if len(plate) != LicencePlateLength {
		return fmt.Errorf("%w: got %d", ErrLicencePlateLength, len(plate))
	}
	want, err := CheckDigit(plate[:LicencePlateLength-1])
	if err != nil {
		return err
	}
	if got := plate[LicencePlateLength-1]; got != want {
		return fmt.Errorf("%w: got %q, want %q", ErrLicencePlateCheckDigit, got, want)
	}
	return nil
}
