import (
	"errors"
	"fmt"
)

// licencePlateLen is the total length of a licence plate: 10 digits plus one
// check character.
const licencePlateLen = 11

// Errors returned by ValidateLicencePlate. Callers can match them with
// errors.Is; the returned errors carry extra detail about what was wrong.
var (
	ErrPlateLength     = errors.New("licence plate must be 11 characters")
	ErrPlateCharacter  = errors.New("licence plate contains an invalid character")
	ErrPlateCheckDigit = errors.New("licence plate check digit does not match")
)

// ValidLicencePlate reports whether lp is a well-formed pallet licence plate.
func ValidLicencePlate(lp string) bool {
	return ValidateLicencePlate(lp) == nil
}

// ValidateLicencePlate checks lp against the pallet licence plate format: ten
// digits followed by a check character. The check character is the sum of each
// digit multiplied by its 1-based position, modulo 11, written as "X" when that
// remainder is 10.
//
// It returns nil if lp is valid, otherwise an error wrapping ErrPlateLength,
// ErrPlateCharacter or ErrPlateCheckDigit.
func ValidateLicencePlate(lp string) error {
	if len(lp) != licencePlateLen {
		return fmt.Errorf("%w, got %d", ErrPlateLength, len(lp))
	}

	sum := 0
	for i := 0; i < licencePlateLen-1; i++ {
		c := lp[i]
		if c < '0' || c > '9' {
			return fmt.Errorf("%w: %q at position %d is not a digit", ErrPlateCharacter, c, i+1)
		}
		sum += int(c-'0') * (i + 1)
	}

	want := checkChar(sum % 11)
	if got := lp[licencePlateLen-1]; got != want {
		if (got < '0' || got > '9') && got != 'X' {
			return fmt.Errorf("%w: check character %q must be a digit or %q", ErrPlateCharacter, got, "X")
		}
		return fmt.Errorf("%w: got %q, want %q", ErrPlateCheckDigit, got, want)
	}
	return nil
}

// checkChar renders a remainder in [0, 10] as its check character.
func checkChar(remainder int) byte {
	if remainder == 10 {
		return 'X'
	}
	return byte('0' + remainder)
}
