func TestLicencePlateCheckDigit(t *testing.T) {
	tests := []struct {
		name string
		body string
		want byte
	}{
		{"all zeros sums to zero", "0000000000", '0'},
		{"leading digit has weight one", "1000000000", '1'},
		{"trailing digit has weight ten", "0000000001", 'X'},
		{"weight nine", "0000000010", '9'},
		{"sum wraps once", "0000000002", '9'},
		{"sum wraps once again", "0000000003", '8'},
		{"sum of 285 is ten, written as X", "1234567890", 'X'},
		{"all nines sum to a multiple of eleven", "9999999999", '0'},
		{"all fives sum to a multiple of eleven", "5555555555", '0'},
		{"transposition changes the check digit", "1200000000", '5'},
		{"transposed pair", "2100000000", '4'},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got, err := LicencePlateCheckDigit(tt.body)
			if err != nil {
				t.Fatalf("LicencePlateCheckDigit(%q) returned error: %v", tt.body, err)
			}
			if got != tt.want {
				t.Errorf("LicencePlateCheckDigit(%q) = %q, want %q", tt.body, got, tt.want)
			}
		})
	}
}

func TestLicencePlateCheckDigitRejectsBadBody(t *testing.T) {
	tests := []struct {
		name string
		body string
	}{
		{"empty", ""},
		{"too short", "123456789"},
		{"too long", "12345678901"},
		{"letter", "123456789A"},
		{"check digit included", "1234567890X"},
		{"space padded", " 123456789"},
		{"sign", "-123456789"},
		{"multibyte", "12345６7890"},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if _, err := LicencePlateCheckDigit(tt.body); !errors.Is(err, ErrLicencePlateBody) {
				t.Errorf("LicencePlateCheckDigit(%q) error = %v, want ErrLicencePlateBody", tt.body, err)
			}
		})
	}
}

func TestValidateLicencePlate(t *testing.T) {
	valid := []string{
		"00000000000",
		"10000000001",
		"0000000001X",
		"00000000109",
		"00000000029",
		"00000000038",
		"1234567890X",
		"99999999990",
		"55555555550",
		"12000000005",
		"21000000004",
	}
	for _, plate := range valid {
		t.Run(plate, func(t *testing.T) {
			if err := ValidateLicencePlate(plate); err != nil {
				t.Errorf("ValidateLicencePlate(%q) = %v, want nil", plate, err)
			}
		})
	}
}

func TestValidateLicencePlateRejectsInvalid(t *testing.T) {
	tests := []struct {
		name  string
		plate string
		want  error
	}{
		{"empty", "", ErrLicencePlateLength},
		{"too short", "1234567890", ErrLicencePlateLength},
		{"too long", "1234567890X0", ErrLicencePlateLength},
		{"multibyte runs long in bytes", "1234567890é", ErrLicencePlateLength},
		{"letter in body", "123456789AX", ErrLicencePlateBody},
		{"X in body", "X234567890X", ErrLicencePlateBody},
		{"hyphenated", "12345-67890", ErrLicencePlateBody},
		{"wrong check digit", "12345678900", ErrLicencePlateCheckDigit},
		{"lowercase x check digit", "1234567890x", ErrLicencePlateCheckDigit},
		{"letter check digit", "1234567890Y", ErrLicencePlateCheckDigit},
		{"X where a digit is required", "0000000000X", ErrLicencePlateCheckDigit},
		{"digit where X is required", "12345678909", ErrLicencePlateCheckDigit},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			err := ValidateLicencePlate(tt.plate)
			if !errors.Is(err, tt.want) {
				t.Errorf("ValidateLicencePlate(%q) error = %v, want %v", tt.plate, err, tt.want)
			}
		})
	}
}

// TestValidateLicencePlateAcceptsGeneratedPlates checks the validator against
// an independent implementation of the weighting rule over a deterministic
// sample of bodies, so a refactoring of either cannot drift unnoticed.
func TestValidateLicencePlateAcceptsGeneratedPlates(t *testing.T) {
	rng := rand.New(rand.NewSource(1))
	for i := 0; i < 2000; i++ {
		body := randomBody(rng)
		plate := body + string(referenceCheckDigit(body))
		if err := ValidateLicencePlate(plate); err != nil {
			t.Fatalf("ValidateLicencePlate(%q) = %v, want nil", plate, err)
		}
	}
}

// TestValidateLicencePlateDetectsSingleDigitErrors and the transposition test
// below cover the two properties position weighting modulo a prime buys us:
// every single-digit substitution and every adjacent transposition is caught.
func TestValidateLicencePlateDetectsSingleDigitErrors(t *testing.T) {
	rng := rand.New(rand.NewSource(2))
	for i := 0; i < 200; i++ {
		body := randomBody(rng)
		plate := body + string(referenceCheckDigit(body))
		for pos := 0; pos < licencePlateBodyLength; pos++ {
			for d := byte('0'); d <= '9'; d++ {
				if d == plate[pos] {
					continue
				}
				corrupt := []byte(plate)
				corrupt[pos] = d
				if err := ValidateLicencePlate(string(corrupt)); !errors.Is(err, ErrLicencePlateCheckDigit) {
					t.Fatalf("ValidateLicencePlate(%q) error = %v, want ErrLicencePlateCheckDigit (corrupted %q at position %d)", corrupt, err, plate, pos+1)
				}
			}
		}
	}
}

func TestValidateLicencePlateDetectsAdjacentTranspositions(t *testing.T) {
	rng := rand.New(rand.NewSource(3))
	for i := 0; i < 200; i++ {
		body := randomBody(rng)
		plate := body + string(referenceCheckDigit(body))
		for pos := 0; pos+1 < licencePlateBodyLength; pos++ {
			if plate[pos] == plate[pos+1] {
				continue // a transposition of equal digits is not an error
			}
			swapped := []byte(plate)
			swapped[pos], swapped[pos+1] = swapped[pos+1], swapped[pos]
			if err := ValidateLicencePlate(string(swapped)); !errors.Is(err, ErrLicencePlateCheckDigit) {
				t.Fatalf("ValidateLicencePlate(%q) error = %v, want ErrLicencePlateCheckDigit (transposed %q at position %d)", swapped, err, plate, pos+1)
			}
		}
	}
}

func randomBody(rng *rand.Rand) string {
