		{"sum of 285 is ten, written as X", "1234567890", 'X'},
		{"all nines sum to a multiple of eleven", "9999999999", '0'},
		{"all fives sum to a multiple of eleven", "5555555555", '0'},
		{"transposition changes the check digit", "1200000000", '5'},
		{"transposed pair", "2100000000", '4'},
