// TestValidateLicencePlateAcceptsGeneratedPlates checks the validator against
// an independent implementation of the weighting rule over a deterministic
// sample of bodies, so a refactoring of either cannot drift unnoticed.
func TestValidateLicencePlateAcceptsGeneratedPlates(t *testing.T) {
	rng := rand.New(rand.NewSource(1))
	for i := 0; i < 2000; i++ {
		body := randomBody(rng)
		plate := body + string(referenceCheckDigit(body))
		if err := ValidateLicencePlate(plate); err != nil {
			t.Fatalf("ValidateLicencePlate(%q) = %v, want nil", plate, err)
		}
	}
}

// TestValidateLicencePlateDetectsSingleDigitErrors and the transposition test
// below cover the two properties position weighting modulo a prime buys us:
// every single-digit substitution and every adjacent transposition is caught.
func TestValidateLicencePlateDetectsSingleDigitErrors(t *testing.T) {
	rng := rand.New(rand.NewSource(2))
	for i := 0; i < 200; i++ {
		body := randomBody(rng)
		plate := body + string(referenceCheckDigit(body))
		for pos := 0; pos < licencePlateBodyLength; pos++ {
			for d := byte('0'); d <= '9'; d++ {
				if d == plate[pos] {
					continue
				}
				corrupt := []byte(plate)
				corrupt[pos] = d
				if err := ValidateLicencePlate(string(corrupt)); !errors.Is(err, ErrLicencePlateCheckDigit) {
					t.Fatalf("ValidateLicencePlate(%q) error = %v, want ErrLicencePlateCheckDigit (corrupted %q at position %d)", corrupt, err, plate, pos+1)
				}
			}
		}
	}
}

func TestValidateLicencePlateDetectsAdjacentTranspositions(t *testing.T) {
	rng := rand.New(rand.NewSource(3))
	for i := 0; i < 200; i++ {
		body := randomBody(rng)
		plate := body + string(referenceCheckDigit(body))
		for pos := 0; pos+1 < licencePlateBodyLength; pos++ {
			if plate[pos] == plate[pos+1] {
				continue // a transposition of equal digits is not an error
			}
			swapped := []byte(plate)
			swapped[pos], swapped[pos+1] = swapped[pos+1], swapped[pos]
			if err := ValidateLicencePlate(string(swapped)); !errors.Is(err, ErrLicencePlateCheckDigit) {
				t.Fatalf("ValidateLicencePlate(%q) error = %v, want ErrLicencePlateCheckDigit (transposed %q at position %d)", swapped, err, plate, pos+1)
			}
		}
	}
}

