	"fmt"
	"testing"
)

func TestValidateLicencePlateAccepts(t *testing.T) {
	// Worked by hand: sum of digit x 1-based position, mod 11.
	tests := []struct {
		name string
		lp   string
	}{
		{"all zeroes, sum 0", "00000000000"},
		{"leading one, sum 1", "10000000001"},
		{"trailing two, sum 20 -> 9", "00000000029"},
		{"ascending, sum 285 -> 10 -> X", "1234567890X"},
		{"descending, sum 165 -> 0", "98765432100"},
		{"all nines, sum 495 -> 0", "99999999990"},
		{"trailing one, sum 10 -> X", "0000000001X"},
		{"five in position two, sum 10 -> X", "0500000000X"},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if err := ValidateLicencePlate(tt.lp); err != nil {
				t.Errorf("ValidateLicencePlate(%q) = %v, want nil", tt.lp, err)
			}
		})
	}
}

func TestValidateLicencePlateRejects(t *testing.T) {
	tests := []struct {
		name    string
		lp      string
		wantErr error
	}{
		{"empty", "", ErrLicencePlateLength},
		{"too short", "1234567890", ErrLicencePlateLength},
		{"too long", "1234567890X0", ErrLicencePlateLength},
		{"body only, no check digit", "0000000000", ErrLicencePlateLength},
		{"multi-byte character inflates length", "1234567890é", ErrLicencePlateLength},

		{"letter in body", "123456789OX", ErrLicencePlateBody},
		{"X in body", "1X3456789 0", ErrLicencePlateBody},
		{"space in body", "1234 678902", ErrLicencePlateBody},
		{"hyphen in body", "12345-67890", ErrLicencePlateBody},
		{"multi-byte character in body", "1234567é0X", ErrLicencePlateBody},

		{"wrong check digit", "12345678905", ErrLicencePlateCheckDigit},
		{"digit where X belongs", "12345678900", ErrLicencePlateCheckDigit},
		{"X where digit belongs", "0000000000X", ErrLicencePlateCheckDigit},
		{"lower-case x is not X", "1234567890x", ErrLicencePlateCheckDigit},
		{"non-alphanumeric check digit", "1234567890+", ErrLicencePlateCheckDigit},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			err := ValidateLicencePlate(tt.lp)
			if !errors.Is(err, tt.wantErr) {
				t.Errorf("ValidateLicencePlate(%q) = %v, want %v", tt.lp, err, tt.wantErr)
			}
		})
	}
}

func TestCheckDigit(t *testing.T) {
	tests := []struct {
		body string
		want byte
	}{
		{"0000000000", '0'},
		{"1000000000", '1'},
		{"0000000002", '9'},
		{"1234567890", 'X'},
		{"9876543210", '0'},
		{"9999999999", '0'},
		{"0000000001", 'X'},
		{"0500000000", 'X'},
	}
	for _, tt := range tests {
		t.Run(tt.body, func(t *testing.T) {
			got, err := CheckDigit(tt.body)
			if err != nil {
				t.Fatalf("CheckDigit(%q) returned error: %v", tt.body, err)
			}
			if got != tt.want {
				t.Errorf("CheckDigit(%q) = %q, want %q", tt.body, got, tt.want)
			}
		})
	}
}

func TestCheckDigitRejects(t *testing.T) {
	tests := []struct {
		name string
		body string
	}{
		{"empty", ""},
		{"nine digits", "123456789"},
		{"whole plate", "1234567890X"},
		{"letter", "12345678AB"},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if _, err := CheckDigit(tt.body); !errors.Is(err, ErrLicencePlateBody) {
				t.Errorf("CheckDigit(%q) = %v, want %v", tt.body, err, ErrLicencePlateBody)
			}
		})
	}
}

// A check digit is only worth having if the plates it produces validate.
func TestCheckDigitRoundTrip(t *testing.T) {
	for n := 0; n < 5000; n++ {
		body := fmt.Sprintf("%010d", n)
		cd, err := CheckDigit(body)
		if err != nil {
			t.Fatalf("CheckDigit(%q) returned error: %v", body, err)
		}
		lp := body + string(cd)
		if err := ValidateLicencePlate(lp); err != nil {
			t.Fatalf("ValidateLicencePlate(%q) = %v, want nil", lp, err)
		}
	}
}

// Mod 11 over 1-based position weights catches every single-digit error, which
// is the main reason to use it over a plain checksum.
func TestValidateLicencePlateCatchesSingleDigitErrors(t *testing.T) {
	const valid = "1234567890X"
	for i := 0; i < licencePlateBodyLength; i++ {
		for d := byte('0'); d <= '9'; d++ {
			if d == valid[i] {
				continue
			}
			corrupt := []byte(valid)
			corrupt[i] = d
			lp := string(corrupt)
			if err := ValidateLicencePlate(lp); !errors.Is(err, ErrLicencePlateCheckDigit) {
				t.Errorf("ValidateLicencePlate(%q) = %v, want %v", lp, err, ErrLicencePlateCheckDigit)
			}
		}
	}
}

// It also catches every transposition of two adjacent, differing digits.
func TestValidateLicencePlateCatchesAdjacentTranspositions(t *testing.T) {
	const valid = "1234567890X"
	for i := 0; i < licencePlateBodyLength-1; i++ {
		if valid[i] == valid[i+1] {
			continue
		}
		corrupt := []byte(valid)
		corrupt[i], corrupt[i+1] = corrupt[i+1], corrupt[i]
		lp := string(corrupt)
		if err := ValidateLicencePlate(lp); !errors.Is(err, ErrLicencePlateCheckDigit) {
			t.Errorf("ValidateLicencePlate(%q) = %v, want %v", lp, err, ErrLicencePlateCheckDigit)
		}
	}
}
