func TestValidateLicencePlateValid(t *testing.T) {
	// One plate per possible check digit, so every remainder of the mod 11 is covered.
	plates := []string{
		"00000000000", // remainder 0
		"00000000501", // remainder 1: 5 in position 9, 5*9 = 45
		"00000000092", // remainder 2: 9 in position 10, 9*10 = 90
		"00000000083",
		"00000000074",
		"00000000065",
		"00000000056",
		"00000000047",
		"00000000038",
		"00000000029",
		"0000000001X", // remainder 10: 1 in position 10, written as X
		"1234567890X", // sum 285, 285 mod 11 = 10
		"98765432100", // sum 165, a multiple of 11
	}
	for _, plate := range plates {
		if err := ValidateLicencePlate(plate); err != nil {
			t.Errorf("ValidateLicencePlate(%q) = %v, want nil", plate, err)
		}
	}
}

func TestValidateLicencePlateInvalid(t *testing.T) {
	tests := []struct {
		name  string
		plate string
		want  error
	}{
		{"empty", "", ErrLicencePlateLength},
		{"too short", "1234567890", ErrLicencePlateLength},
		{"too long", "1234567890X0", ErrLicencePlateLength},
		{"body missing a digit", "123456789 X", ErrLicencePlateBody},
		{"letter in body", "12345A7890X", ErrLicencePlateBody},
		{"X in body", "1234567X90X", ErrLicencePlateBody},
		{"multibyte body", "123456789é0", ErrLicencePlateBody}, // 11 bytes, 10 runes
		{"wrong check digit", "12345678909", ErrLicencePlateCheckDigit},
		{"X where a digit is expected", "9876543210X", ErrLicencePlateCheckDigit},
		{"lowercase x", "1234567890x", ErrLicencePlateCheckDigit},
		{"letter check digit", "1234567890A", ErrLicencePlateCheckDigit},
		{"altered digit", "1234567891X", ErrLicencePlateCheckDigit},
		{"transposed digits", "2134567890X", ErrLicencePlateCheckDigit},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			err := ValidateLicencePlate(tt.plate)
			if !errors.Is(err, tt.want) {
				t.Errorf("ValidateLicencePlate(%q) = %v, want %v", tt.plate, err, tt.want)
			}
		})
	}
}

// Any single-digit change must break the check digit, since each digit is weighted
// by a distinct position and 11 is prime.
func TestValidateLicencePlateRejectsSingleDigitChanges(t *testing.T) {
	const valid = "1234567890X"
	for i := 0; i < LicencePlateLength-1; i++ {
		for d := byte('0'); d <= '9'; d++ {
			if d == valid[i] {
				continue
			}
			plate := valid[:i] + string(d) + valid[i+1:]
			if err := ValidateLicencePlate(plate); !errors.Is(err, ErrLicencePlateCheckDigit) {
				t.Errorf("ValidateLicencePlate(%q) = %v, want %v", plate, err, ErrLicencePlateCheckDigit)
			}
		}
	}
}

// Swapping two adjacent, differing digits shifts the weighted sum by their
// difference, so it must always be caught.
func TestValidateLicencePlateRejectsAdjacentTranspositions(t *testing.T) {
	const valid = "1234567890X"
	for i := 0; i < LicencePlateLength-2; i++ {
		if valid[i] == valid[i+1] {
			continue
		}
		plate := valid[:i] + string(valid[i+1]) + string(valid[i]) + valid[i+2:]
		if err := ValidateLicencePlate(plate); !errors.Is(err, ErrLicencePlateCheckDigit) {
			t.Errorf("ValidateLicencePlate(%q) = %v, want %v", plate, err, ErrLicencePlateCheckDigit)
		}
	}
}

func TestLicencePlateCheckDigit(t *testing.T) {
	tests := []struct {
		body string
		want byte
	}{
		{"0000000000", '0'},
		{"1000000000", '1'},
		{"0000000100", '8'},
		{"1234567890", 'X'},
		{"9876543210", '0'},
		{"9999999999", '0'}, // 9 * 55 = 495 = 45 * 11
	}
	for _, tt := range tests {
		if got := licencePlateCheckDigit(tt.body); got != tt.want {
			t.Errorf("licencePlateCheckDigit(%q) = %q, want %q", tt.body, got, tt.want)
		}
	}
}
