import (
	"errors"
	"fmt"
)

// LicencePlateLength is the total number of characters in a licence plate:
// ten body digits followed by one check digit.
const LicencePlateLength = 11

// licencePlateBodyLength is the number of digits the check digit is computed from.
const licencePlateBodyLength = LicencePlateLength - 1

var (
	// ErrLicencePlateLength reports a licence plate of the wrong length.
	ErrLicencePlateLength = errors.New("licence plate must be 11 characters")

	// ErrLicencePlateChar reports a body character that is not an ASCII digit.
	ErrLicencePlateChar = errors.New("licence plate body must be digits")

	// ErrLicencePlateCheckDigit reports a check digit that does not match the body.
	ErrLicencePlateCheckDigit = errors.New("licence plate check digit does not match")
)

// CheckDigit returns the check digit character for the ten body digits of a
// licence plate. Each digit is multiplied by its 1-based position, the products
// are summed and reduced mod 11; a remainder of 10 is written as 'X'.
func CheckDigit(body string) (byte, error) {
	if len(body) != licencePlateBodyLength {
		return 0, fmt.Errorf("%w: body must be %d digits, got %d", ErrLicencePlateLength, licencePlateBodyLength, len(body))
	}

	sum := 0
	for i := 0; i < len(body); i++ {
		c := body[i]
		if c < '0' || c > '9' {
			return 0, fmt.Errorf("%w: %q at position %d is not a digit", ErrLicencePlateChar, c, i+1)
		}
		sum += int(c-'0') * (i + 1)
	}

	r := sum % 11
	if r == 10 {
		return 'X', nil
	}
	return byte('0' + r), nil
}

// ValidateLicencePlate checks that s is a well-formed pallet licence plate:
// ten digits followed by the check digit computed by CheckDigit. It returns nil
// if the plate is valid, otherwise an error wrapping one of
// ErrLicencePlateLength, ErrLicencePlateChar or ErrLicencePlateCheckDigit.
func ValidateLicencePlate(s string) error {
	if len(s) != LicencePlateLength {
		return fmt.Errorf("%w: got %d", ErrLicencePlateLength, len(s))
	}

	want, err := CheckDigit(s[:licencePlateBodyLength])
	if err != nil {
		return err
	}

	if got := s[licencePlateBodyLength]; got != want {
		return fmt.Errorf("%w: expected %q, got %q", ErrLicencePlateCheckDigit, want, got)
	}
	return nil
}
